Object.assign(TR.things, {
  kraftwerk: ["Hydro power plant", "High up in the mountains a huge wall holds back the water to make a lake. The Grande Dixence in Valais is 285 metres high – the tallest dam in Switzerland! The water rushes down pipes into the valley and spins turbines that make electricity. More than half of Swiss electricity comes from water power."],
  bergwerk: ["Iron mine", "In the Gonzen near Sargans, miners dug iron ore out of the mountain for over 2000 years – in tunnels that are 90 kilometres long altogether! Ore is rock with lots of iron in it. Today the mine is a museum: you ride into the mountain on a little mine train."],
  stahlwerk: ["Steelworks", "In the furnace the ore gets so hot that the iron melts – over 1500 °C! The liquid iron glows orange like lava. Add a little carbon and it becomes steel: hard but still bendy. Today the Gerlafingen steelworks mostly melts down old iron – that's recycling!"],
  messerschmiede: ["Swiss Army knife forge", "Karl Elsener made the red Swiss Army knife in Ibach, canton Schwyz, in 1891 for the soldiers. It has a blade, screwdriver, can opener and awl – some have over 30 tools! Today the company is called Victorinox and makes tens of thousands of knives every day."],
  zahnradwerk: ["Gear factory", "Gears mesh with their teeth: when one turns, the other turns too. A small wheel turns fast, a big one slowly but strongly. The teeth are milled very precisely out of steel, otherwise it grinds and gets stuck. Without gears there would be no bikes, clocks or rack railways!"],
  liftfabrik: ["Lift factory", "Robert Schindler opened a workshop in Lucerne in 1874 – today Schindler builds lifts and escalators for the whole world. A lift hangs on strong steel ropes. On the other side hangs a heavy counterweight, so the motor needs little power. And if a rope breaks, safety brakes grab the rails."],
  lokfabrik: ["Locomotive factory", "In Winterthur the SLM built locomotives for over 100 years, including the famous 'Crocodile' for the Gotthard line – long, brown and with a joint in the middle. Today Stadler in Thurgau builds trains that run in many countries. An electric locomotive takes its power from the overhead line with the pantograph on top."],
  seilbahnwerk: ["Cable car works", "Cable cars from Switzerland run all over the world. The carrying rope is thicker than your arm and twisted from many steel wires. One cabin up the Stanserhorn even has an open top deck – people stand on the roof in the wind!"],
  flugzeugwerk: ["Aircraft works", "In Stans in Nidwalden, Pilatus builds small aeroplanes. They can even land on meadows, snow and short mountain runways – that's why doctors in Australia use them to fly to faraway farms. A propeller is like a twisted wing: it pulls the plane through the air."],
  goldwaschplatz: ["Gold panning spot", "In the Napf area in the Emmental there is real gold in the streams! Tiny grains that the water has washed out of the mountain. You swirl sand and water in a pan – the heavy gold sinks to the bottom and stays there. A few grains a day is already lucky."],
  rubinofen: ["Ruby furnace", "Every good watch has little red rubies inside: the axles of the tiny wheels turn in them and hardly wear out. The stones are grown artificially in a furnace: fine powder trickles through a hot flame and grows drop by drop into a ruby. A company in Monthey in Valais has done this for over 100 years."],
  goldraffinerie: ["Gold refinery", "Some of the biggest gold refineries in the world are in Ticino – a large share of all gold is purified in Switzerland! The gold is melted and everything else is removed until it is almost completely pure: 999.9 parts in 1000. Then it is poured into bars and stamped with its weight and purity."],
  uhrwerkfabrik: ["Watch movement factory", "The movement is the heart of a watch. A wound-up spring releases its power very slowly, and the balance wheel swings back and forth – tick, tock, several times a second. In Grenchen and the Jura millions of movements are made, with wheels smaller than a grain of rice."],
  plastikuhrfabrik: ["Plastic watch factory", "Around 1980, watches from Japan were cheap and the Swiss watchmakers were in trouble. Then engineers in Biel invented a colourful plastic watch with only 51 parts: the Swatch (1983). Because a machine assembles it, it is cheap. It was a huge success and saved the Swiss watch industry!"],
  taschenuhratelier: ["Pocket watch workshop", "Over 400 years ago people in Geneva were no longer allowed to wear jewellery – so the goldsmiths started making watches instead. In the old days you wore your watch on a chain in your waistcoat pocket. Press the crown and the golden lid springs open."],
  monduhrwerk: ["Moon watch works", "When the first people landed on the Moon in 1969, they wore a Swiss watch from Biel on their arm – over the spacesuit! NASA had tested it hard: in heat, cold, shaking and without air. With the stopwatch button astronauts could time things when a device failed."],
  uhrenmanufaktur: ["Watch manufacture", "Winter is long in the Vallée de Joux in the Jura. Long ago the farmers there built watches in their warm living rooms during the cold months – that's how famous manufactures began. A master watch has over 1000 parts: it shows the Moon, chimes the hours like a little bell and even knows when it's a leap year."],
  spieldosen: ["Music box workshop", "In Sainte-Croix in the Jura, music boxes have been made for 200 years. A cylinder with tiny pins turns, and each pin plucks a tooth of a steel comb – pling! Short teeth sound high, long ones low. It is wound up with a spring, just like a watch."],
  bankschalter: ["Bank counter", "At the bank counter people bring their money to the bank – children too, with their piggy bank! The bank looks after the money and lends it to others, for example to build a house. In return you get a little interest: your savings grow a bit all by themselves."],
  muenzstaette: ["Mint", "In Bern, Swissmint makes all Swiss coins. A press stamps a picture onto a metal disc with great force. The Gold Vreneli is a famous gold coin with the head of Helvetia. It was minted from 1897 to 1949 and is still a popular present today."],
  kantonalbank: ["Cantonal bank", "Almost every canton has its own bank, the cantonal bank. In the old days every child got a savings book: at every visit to the counter they wrote in it how much money was saved. Today you usually see that on a phone."],
  notendruckerei: ["Banknote printers", "Swiss banknotes are printed in Zurich for the National Bank. The paper isn't made of wood but of cotton fibres, with plastic in the middle. Hold a note up to the light and you'll see a hidden Swiss cross! The 10 is yellow, the 20 red, the 50 green, the 100 blue."],
  privatbank: ["Private bank with vault", "On Paradeplatz in Zurich big banks stand side by side. Deep underground there are vaults with thick steel doors. People rent safe-deposit boxes there for valuables: gold, jewellery, old watches. A vault door can weigh as much as three elephants – and still opens easily because it is perfectly balanced."],
  gewaechshaus: ["Medicinal plant greenhouse", "Many medicines originally come from plants. Willow bark contains a remedy for pain and fever, foxglove one for the heart. In the warm greenhouse the plants grow all year round. Researchers study which substances are inside and how they work."],
  saline: ["Saltworks", "200 million years ago there was a sea here. When it dried up, salt was left deep in the ground. In Bex in Vaud there is a salt mine, and by the Rhine they pump water down that dissolves the salt. The salty water comes back up, the water evaporates – and salt is left, also for gritting roads in winter."],
  chemiewerk: ["Chemical works on the Rhine", "In Basel it all started with dyes: over 150 years ago factories on the Rhine dyed fabrics. These dye factories grew into big pharma companies that today make medicines for the whole world. In the lab the important substance is extracted from the plant and made completely pure – the active ingredient."],
  tablettenfabrik: ["Tablet factory", "A tablet often contains only a tiny amount of active ingredient. To make it easy to swallow, it is mixed with sugar or starch and a machine presses the powder into little discs – thousands per minute! But you only take medicine when a doctor says so."],
  infusionswerk: ["Infusion works", "People who are very weak in hospital sometimes get a drip: liquid drips from a bag through a thin tube into the blood. Usually it is water with exactly as much salt as in your blood – 9 grams in a litre. It has to be completely germ-free!"],
  impfstofflabor: ["Vaccine lab", "A vaccination is like a practice alarm for the body: it gets to know a germ without getting ill. When the real germ comes, the defences are already ready. Funny fact: flu vaccine is often grown in hens' eggs – millions of vaccinations need millions of eggs!"],
  vitaminwerk: ["Vitamin works", "Vitamin C keeps you healthy – it's in strawberries, lemons and peppers. In 1933 the chemist Tadeus Reichstein in Zurich found out how to make vitamin C artificially. A Basel company turned it into tablets for the whole world. Drop a fizzy tablet into water and it bubbles!"],
  pflasterfabrik: ["Plaster factory", "A plaster has three layers: in the middle the soft pad for the wound, around it the glue and on the outside a fabric that lets air through. Sometimes the pad contains something against germs. In Flawil in canton St. Gallen, cotton wool and bandages have been made for over 150 years."],
  rotkreuzdepot: ["Red Cross depot", "In 1859 Henri Dunant from Geneva saw a terrible battle where nobody cared for the wounded. So he founded the Red Cross. Its sign is the Swiss flag reversed: a red cross on white. To this day the Red Cross brings help wherever people are in need. Dunant received the very first Nobel Peace Prize for it."],
  quarzgrube: ["Quartz sand pit", "Sand looks boring, but many grains are quartz – and that contains silicon, the most important material for computer chips! Quartz sand is also used to make glass. In the Alps you can even find big, clear rock crystals: they are quartz too. Crystal hunters search for them in rock crevices."],
  solarpark: ["Alpine solar park", "Solar cells turn sunlight straight into electricity – without any noise. In the mountains the sun shines above the sea of fog, and the snow reflects even more light onto the cells. On the dam of Lake Mutt in Glarus hangs one of the highest solar plants in Europe, at almost 2500 metres."],
  siliziumwerk: ["Silicon works", "Quartz sand is melted at almost 2000 °C until pure silicon is left. From it a thick, shiny rod – a crystal – is slowly pulled out. It is sawn into wafer-thin discs as smooth as a mirror. Hundreds of computer chips fit on one disc."],
  chipfabrik: ["Microchip factory", "A chip is a tiny plate full of minute switches – billions of them! They are so small that a speck of dust is huge next to them. That's why people work in a clean room, with suit, hood and mask. Fine gold wires connect the chip to its little legs. In Marin on Lake Neuchâtel, chips are made for watches and bike computers."],
  mausfabrik: ["Computer mouse factory", "Logitech was founded in 1981 in Apples in canton Vaud – on a farm! The company became famous for computer mice and has already sold over a billion. Underneath a mouse a light shines, and a tiny camera photographs the table thousands of times a second to notice where you push it."],
  roboterwerk: ["Robot works", "Industrial robots are strong arms with six joints – like shoulder, elbow and wrist. They weld cars together, pack chocolate into boxes or paint. A chip tells each motor exactly how far to turn. ABB from Zurich builds such robots for factories all over the world."],
  drohnenwerk: ["Drone workshop", "Around Zurich and Lausanne there are so many drone companies that people talk of 'Drone Valley'. A drone usually has four propellers. If one spins faster, it tilts and flies in that direction. Some drones fly into caves and tanks to look for damage, others carry blood samples from hospital to hospital."],
  serverhalle: ["Data centre in the mountain", "In the Alps there are old army bunkers deep in the rock. Today some of them hold computers that store data safely – behind steel doors, protected from lightning and floods. Data is everything a computer stores: photos, texts, weather numbers. An AI can learn from lots of data."],
  supercomputer: ["Supercomputer", "In Lugano stands one of the fastest computers in Europe. In one second it calculates more than all the people in the world together could in a whole year – even if each did one sum every second. MeteoSwiss uses it to forecast the weather, and researchers train AI on it. It is cooled with water from Lake Lugano!"],
  kilabor: ["AI lab", "An AI learns a bit like you: from lots of examples. Show it thousands of pictures of cows and it remembers what a cow looks like. At ETH Zurich and EPFL in Lausanne many people research AI. Important: an AI can be wrong too – so a human always has to think along."],
  uebersetzerwerk: ["Translator workshop", "Switzerland has four national languages: German, French, Italian and Romansh. An AI translator listens and says the same thing in another language – 'Grüezi', 'Bonjour', 'Buongiorno', 'Allegra'! It learned from millions of texts which words belong together."],
  laufroboterwerk: ["Walking robot works", "At ETH Zurich researchers built a robot with four legs that looks like a dog. It climbs stairs, gets back up when it falls over and inspects tunnels and power plants where it is dangerous for people. With its AI it learns by itself how to walk on ice and stones."],
  expohalle: ["National exhibition", "Two hundred land levels – that deserves a national exhibition! Every now and then Switzerland shows what it can do at an Expo: in 1939 at the 'Landi' in Zurich, in 1964 in Lausanne and in 2002 at Expo.02 with pavilions on the water. Your pavilion has everything together: watch, locomotive, Red Cross case, walking robot – and of course chocolate!"],
});
Object.assign(TR.tools, {
  werk: ["Works yard equipment", [
    ["Hands", "Carrying ore with your bare hands? Phew – after two lumps you need a break."],
    ["Ladder wagon", "A wooden cart with ladders as sides. You pull it by the shaft – lots of ore lumps and heavy batteries fit inside."],
    ["Forklift", "Two strong forks slide under the pallet and lift it. At the back hangs a heavy counterweight so the forklift doesn't tip forwards."],
    ["Conveyor belt", "A long rubber belt runs over rollers from the tunnel to the works. Ore and power batteries travel to their destination all by themselves. CONVEYS AUTOMATICALLY!"],
  ]],
  uhrmacher: ["Watchmaker's tools", [
    ["Hands", "Picking up gold grains with your fingers? They are so tiny they keep falling out."],
    ["Gold pan", "A flat pan with ridges: you swirl sand and water until only the heavy gold glitters."],
    ["Loupe and tweezers", "Watchmakers squeeze a loupe into their eye and grab tiny parts with fine tweezers. A ruby is sometimes smaller than a grain of sand!"],
    ["Sorting robot", "A camera recognises every grain and every stone, and a little gripper sorts them into bowls in a flash. COLLECTS AUTOMATICALLY!"],
  ]],
  bank: ["Bank equipment", [
    ["Hands", "Pockets full of coins – it jingles at every step, and some roll away!"],
    ["Money bag", "A strong linen sack with a cord. The amount is written on it so nobody has to count again."],
    ["Money counting machine", "The machine counts coins and notes in a flash – 1000 notes a minute – and even notices a fake one."],
    ["Security van", "An armoured van with thick walls brings the money safely to the vault. When it drives is a secret. DRIVES AUTOMATICALLY!"],
  ]],
  labor: ["Lab equipment", [
    ["Hands", "Into the lab without gloves? No, no – wash your hands first! And picking plants is slow."],
    ["Lab coat and gloves", "A white coat and gloves protect you and the samples. That way no germs get in from your fingers."],
    ["Pipette and cool box", "With the pipette you suck up tiny drops very precisely. In the cool box samples stay fresh until they reach the lab."],
    ["Lab robot", "A robot fills hundreds of tubes at once, day and night – without getting tired and without shaking. WORKS AUTOMATICALLY!"],
  ]],
  technik: ["Tech equipment", [
    ["Hands", "The sand trickles through your fingers, and the solar cells are covered in dust."],
    ["Shovel and sieve", "With the sieve you separate fine quartz sand from stones. And with a soft brush you clean the solar cells – clean ones give more power."],
    ["Wheel loader", "A wheel loader has a huge bucket at the front. One load carries as much sand as a hundred children with buckets."],
    ["Cleaning and loading robots", "Robot carts drive through the innovation park by themselves, fetch sand and clean the solar cells. They find their way with cameras and lasers. WORKS AUTOMATICALLY!"],
  ]],
  daten: ["Data line", [
    ["Hands", "You can't touch data! So you copy the numbers onto little notes …"],
    ["USB stick", "Thousands of books fit on such a small stick. Plug in, copy, take it with you."],
    ["Fibre-optic cable", "In a fibre-optic cable, data zips through glass threads thinner than a hair as flashes of light – almost as fast as light itself."],
    ["AI assistant", "An AI assistant sorts the data by itself and sends it wherever it's needed. You still check that everything is right! WORKS AUTOMATICALLY!"],
  ]],
});

// New business centres (land levels 210–300)
